import java.util.HashMap;
import java.util.Map;

class Solution {
    public int countTriplets(int[] nums) {
        Map<Integer, Integer> valueFrequency = new HashMap<>();
        for (int value : nums) {
            valueFrequency.merge(value, 1, Integer::sum);
        }

        Map<Integer, Integer> pairCount = new HashMap<>();
        for (Map.Entry<Integer, Integer> first : valueFrequency.entrySet()) {
            for (Map.Entry<Integer, Integer> second : valueFrequency.entrySet()) {
                int mask = first.getKey() & second.getKey();
                int orderedPairs = first.getValue() * second.getValue();
                pairCount.merge(mask, orderedPairs, Integer::sum);
            }
        }

        int answer = 0;
        for (int c : nums) {
            for (Map.Entry<Integer, Integer> entry : pairCount.entrySet()) {
                if ((entry.getKey() & c) == 0) {
                    answer += entry.getValue();
                }
            }
        }
        return answer;
    }
}

class Solution {
    private static final int BITS = 16;
    private static final int LIMIT = 1 << BITS;
    private static final int FULL_MASK = LIMIT - 1;

    public int countTriplets(int[] nums) {
        int[] pairCount = new int[LIMIT];
        for (int a : nums) {
            for (int b : nums) {
                pairCount[a & b]++;
            }
        }

        int answer = 0;
        for (int c : nums) {
            int complement = FULL_MASK ^ c;
            for (int sub = complement;; sub = (sub - 1) & complement) {
                answer += pairCount[sub];
                if (sub == 0) {
                    break;
                }
            }
        }
        return answer;
    }
}

class Solution {
    private static final int BITS = 16;
    private static final int LIMIT = 1 << BITS;
    private static final int FULL_MASK = LIMIT - 1;

    public int countTriplets(int[] nums) {
        int[] subsetSum = new int[LIMIT];
        for (int a : nums) {
            for (int b : nums) {
                subsetSum[a & b]++;
            }
        }

        for (int bit = 0; bit < BITS; bit++) {
            for (int mask = 0; mask < LIMIT; mask++) {
                if ((mask & (1 << bit)) != 0) {
                    subsetSum[mask] += subsetSum[mask ^ (1 << bit)];
                }
            }
        }

        int answer = 0;
        for (int c : nums) {
            answer += subsetSum[FULL_MASK ^ c];
        }
        return answer;
    }
}

class Solution {
    private static final int BITS = 16;

    public int countTriplets(int[] nums) {
        Node root = new Node();
        for (int a : nums) {
            for (int b : nums) {
                insert(root, a & b);
            }
        }

        int answer = 0;
        for (int value : nums) {
            answer += query(root, value, BITS - 1);
        }
        return answer;
    }

    private void insert(Node node, int mask) {
        for (int bit = BITS - 1; bit >= 0; bit--) {
            if ((mask & (1 << bit)) == 0) {
                if (node.zero == null) {
                    node.zero = new Node();
                }
                node = node.zero;
            } else {
                if (node.one == null) {
                    node.one = new Node();
                }
                node = node.one;
            }
        }
        node.count++;
    }

    private int query(Node node, int value, int bit) {
        if (node == null) {
            return 0;
        }
        if (bit < 0) {
            return node.count;
        }
        if ((value & (1 << bit)) != 0) {
            return query(node.zero, value, bit - 1);
        }
        return query(node.zero, value, bit - 1) + query(node.one, value, bit - 1);
    }

    private static final class Node {
        Node zero;
        Node one;
        int count;
    }
}
